<div class="pos-layout"><section><div class="panel"><div class="panel-head"><div><h2>Sale Point</h2><p>Final bill posts order, payment, inventory and kitchen print jobs in one local transaction</p></div><div class="spacer"></div><input id="posSearch" placeholder="Search menu..." style="max-width:260px"></div><div class="panel-body"><div class="product-grid" id="productGrid"><?php foreach($menu as $m):?><article class="product" data-id="<?=$m['id']?>" data-name="<?=e($m['name'])?>" data-price="<?=$m['base_price']?>"><div class="pic"><?=strtoupper(substr($m['name'],0,1))?></div><div class="copy"><b><?=e($m['name'])?></b><small><?=e($m['category_name'])?> · <?=money($m['base_price'])?></small></div></article><?php endforeach;?></div></div></div></section><aside class="panel"><div class="panel-head"><div><h2>Current Bill</h2><p id="billNo">Bill #<?=e($nextBill)?></p></div></div><div class="panel-body"><div id="cart"></div><div class="cart-total"><div><span>Subtotal</span><b id="subtotal">PKR 0.00</b></div><div><span>Tax</span><b><input id="tax" type="number" step="0.01" value="0" style="width:90px;height:30px"></b></div><div><span>Discount</span><b><input id="discount" type="number" step="0.01" value="0" style="width:90px;height:30px"></b></div><div class="grand"><span>Grand Total</span><b id="grand">PKR 0.00</b></div></div><div class="form-grid" style="margin-top:8px"><label><span>Mode</span><select id="mode"><option value="DINE_IN">Dine In</option><option value="TAKEAWAY">Takeaway</option><option value="DELIVERY">Delivery</option></select></label><label><span>Payment</span><select id="payment"><?php foreach($payments as $p):?><option value="<?=$p['code']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label><span>Received</span><input id="received" type="number" step="0.01" value="0"></label><label><span>Shift</span><select id="shift"><option value="">No Shift</option><?php foreach($shifts as $s):?><option value="<?=$s['id']?>"><?=e($s['shift_no'])?></option><?php endforeach;?></select></label></div><button class="btn primary" id="closeBill" style="width:100%;height:46px;margin-top:9px">Close Bill & Print Queue</button></div></aside></div><form id="posForm" method="post" action="/?r=pos-finalize" style="display:none"><?=csrf_field()?><input name="payload" id="payload"></form><script>
const cart=[];const money=n=>'PKR '+Number(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function render(){const box=document.getElementById('cart');box.innerHTML=cart.map((x,i)=>`<div class="cart-row"><input type="number" min=".001" step=".001" value="${x.qty}" data-q="${i}" style="height:30px;padding:0 4px"><b>${x.name}</b><span>${money(x.price)}</span><b>${money(x.qty*x.price)}</b><button class="btn red" style="height:28px;padding:0" data-del="${i}">×</button></div>`).join('');const sub=cart.reduce((a,x)=>a+x.qty*x.price,0),tax=+document.getElementById('tax').value||0,dis=+document.getElementById('discount').value||0;document.getElementById('subtotal').textContent=money(sub);document.getElementById('grand').textContent=money(sub+tax-dis);}
document.querySelectorAll('.product').forEach(p=>p.onclick=()=>{const x=cart.find(x=>x.id===p.dataset.id);if(x)x.qty++;else cart.push({id:p.dataset.id,name:p.dataset.name,price:+p.dataset.price,qty:1});render()});document.addEventListener('input',e=>{if(e.target.dataset.q!==undefined){cart[+e.target.dataset.q].qty=+e.target.value;render()}if(['tax','discount'].includes(e.target.id))render()});document.addEventListener('click',e=>{if(e.target.dataset.del!==undefined){cart.splice(+e.target.dataset.del,1);render()}});document.getElementById('posSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.product').forEach(p=>p.style.display=p.dataset.name.toLowerCase().includes(q)?'':'none')};document.getElementById('closeBill').onclick=()=>{if(!cart.length)return alert('Add items first');const sub=cart.reduce((a,x)=>a+x.qty*x.price,0),tax=+taxEl.value||0,discount=+discountEl.value||0,grand=sub+tax-discount,received=+document.getElementById('received').value||0;if(received<grand&&document.getElementById('payment').value==='CASH')return alert('Received amount is less than total');document.getElementById('payload').value=JSON.stringify({bill_no:'<?=e($nextBill)?>',service_mode:document.getElementById('mode').value,payment_code:document.getElementById('payment').value,received_amount:received,tax_amount:tax,discount_amount:discount,service_charge:0,shift_id:document.getElementById('shift').value,items:cart.map(x=>({menu_item_id:x.id,qty:x.qty,unit_price:x.price}))});document.getElementById('posForm').submit()};const taxEl=document.getElementById('tax'),discountEl=document.getElementById('discount');render();</script>